V4_CSS = '\n/* Thunderstorm, the tier above On fire (17 Oct 2026, Christopher; build/storm_tier.py): hot, 7+ games and 2.5+ NHL\n   points a game.  Fourth version, same night ("more subtle", then Super Saiyan 2 style, then "high quality\n   lightning"): a bigger flame, a soft blue ring that pulses around the portrait, and real lightning drawn live on a\n   small canvas: every bolt is generated fresh (fractal, forked, flickering, white core in a blue glow) and crackles\n   off the rim at random.  The row itself stays still.  Paused off screen; one still bolt under reduced motion. */\n.fw.storm{--fls:1.4}\n.fw.storm>.fbolt{position:absolute;z-index:2;pointer-events:none;left:-120%;right:-120%;top:-120%;bottom:-120%}\n.fw.storm>.fbolt::before{content:"";position:absolute;inset:33.5%;border-radius:50%;background:radial-gradient(circle,rgba(170,220,255,0) 55%,rgba(170,220,255,.42) 64%,rgba(120,190,255,0) 74%);animation:staura 1.6s ease-in-out infinite}\n.fw.storm>.fbolt canvas{position:absolute;inset:0;width:100%;height:100%;display:block}\n.fw.storm>.face{box-shadow:0 0 0 1.5px rgba(200,235,255,.7);animation:string 1.6s ease-in-out infinite}\n@keyframes staura{0%,100%{opacity:.35;transform:scale(.97)}50%{opacity:.9;transform:scale(1.04)}}\n@keyframes string{0%,100%{box-shadow:0 0 0 1.5px rgba(200,235,255,.55),0 0 8px 1px rgba(120,190,255,.25)}50%{box-shadow:0 0 0 1.5px rgba(220,242,255,.9),0 0 16px 3px rgba(120,190,255,.45)}}\n@media(prefers-reduced-motion:reduce){.fw.storm>.fbolt::before,.fw.storm>.face{animation:none!important}}'
V4_JS = '/* Thunderstorm tier (17 Oct 2026; build/storm_tier.py): above On fire, for a hot run of 2.5+ NHL points a game over 7+ games */\nfunction isStorm(x){return !!x&&x.k==="hot"&&(x.gp||0)>=7&&(x.ppg||0)>=2.5;}\nfunction boltArt(){return `<i class="fbolt"><canvas aria-hidden="true"></canvas></i>`;}\n/* the lightning: one loop for every storm portrait on the page; each canvas keeps its own bolts */\n(function(){\n  if(window.__stormLoop)return;window.__stormLoop=1;\n  const still=matchMedia("(prefers-reduced-motion: reduce)").matches,ST=new WeakMap(),R=(a,b)=>a+Math.random()*(b-a);\n  /* a fractal bolt: midpoint displacement, then forks that branch off and taper */\n  function path(x1,y1,x2,y2,rough,depth){let p=[[x1,y1],[x2,y2]];\n    for(let d=0;d<depth;d++){const n=[p[0]];for(let i=1;i<p.length;i++){const [ax,ay]=p[i-1],[bx,by]=p[i],dx=bx-ax,dy=by-ay,L=Math.hypot(dx,dy),o=R(-1,1)*L*rough;\n      n.push([(ax+bx)/2-dy/L*o,(ay+by)/2+dx/L*o],[bx,by]);}p=n;rough*=.72;}return p;}\n  function bolt(cx,cy,r,s){const a=R(0,Math.PI*2)-(Math.random()<.55?Math.PI/2*R(0,1):0),r0=r*R(.9,1),len=r*R(.95,1.75),b=a+R(-.45,.45);\n    const main=path(cx+Math.cos(a)*r0,cy+Math.sin(a)*r0,cx+Math.cos(b)*(r0+len),cy+Math.sin(b)*(r0+len),.62,7),segs=[{p:main,w:1}];\n    for(let k=0;k<4;k++){if(Math.random()<.7){const i=(main.length*R(.2,.75))|0,[bx,by]=main[i],ba=Math.atan2(by-cy,bx-cx)+R(-1,1),bl=len*R(.25,.5);\n      const br=path(bx,by,bx+Math.cos(ba)*bl,by+Math.sin(ba)*bl,.6,6);segs.push({p:br,w:.55});\n      if(Math.random()<.4){const j=(br.length*R(.3,.7))|0,[qx,qy]=br[j],qa=ba+R(-1,1),ql=bl*R(.3,.5);segs.push({p:path(qx,qy,qx+Math.cos(qa)*ql,qy+Math.sin(qa)*ql,.5,4),w:.3});}}}\n    return {segs,life:0,max:R(11,18)|0,hx:main[0][0],hy:main[0][1],s};}\n  const FLK=[1,.35,1,.85,.2,.9,.6,.3,.75,.45,.2,.5,.3,.15,.25,.1];\n  function draw(c,b){const f=FLK[Math.min(FLK.length-1,b.life)]*(1-b.life/b.max*.4);if(f<=0)return;\n    c.globalCompositeOperation="lighter";\n    const g=c.createRadialGradient(b.hx,b.hy,0,b.hx,b.hy,b.s*18);g.addColorStop(0,`rgba(140,200,255,${.18*f})`);g.addColorStop(1,"rgba(140,200,255,0)");c.fillStyle=g;c.fillRect(b.hx-b.s*18,b.hy-b.s*18,b.s*36,b.s*36);\n    for(const [col,wd,al,blur] of [["70,150,255",4.2,.38,10],["170,220,255",1.8,.95,5],["255,255,255",.85,1,2]]){\n      c.strokeStyle=`rgba(${col},${al*f})`;c.shadowColor=`rgba(${col},${f})`;c.shadowBlur=blur*b.s;\n      for(const sg of b.segs){c.lineWidth=wd*sg.w*b.s;c.beginPath();sg.p.forEach((q,i)=>i?c.lineTo(q[0],q[1]):c.moveTo(q[0],q[1]));c.stroke();}}\n    c.shadowBlur=0;}\n  function tick(){const vh=innerHeight;\n    document.querySelectorAll(".fw.storm>.fbolt>canvas").forEach(cv=>{const rc=cv.getBoundingClientRect();if(!rc.width||rc.bottom<0||rc.top>vh)return;\n      let st=ST.get(cv);const dpr=Math.min(3,devicePixelRatio||1),W=Math.round(rc.width*dpr),H=Math.round(rc.height*dpr);\n      if(!st){st={b:[],next:R(4,20)|0};ST.set(cv,st);}\n      if(cv.width!==W||cv.height!==H){cv.width=W;cv.height=H;}\n      const c=cv.getContext("2d"),cx=W/2,cy=H/2,r=W/2/3.4,s=W/(210*dpr);\n      c.setTransform(1,0,0,1,0,0);c.clearRect(0,0,W,H);\n      if(--st.next<=0){st.b.push(bolt(cx,cy,r,s*dpr));if(Math.random()<.3)st.b.push(bolt(cx,cy,r,s*dpr));st.next=R(8,30)|0;}\n      for(let i=st.b.length-1;i>=0;i--){const b=st.b[i];draw(c,b);b.life++;if(b.life>=b.max)st.b.splice(i,1);}});\n    if(!still)requestAnimationFrame(tick);}\n  if(still){setTimeout(()=>{document.querySelectorAll(".fw.storm>.fbolt>canvas").forEach(cv=>{const rc=cv.getBoundingClientRect(),d=Math.min(2,devicePixelRatio||1);cv.width=rc.width*d;cv.height=rc.height*d;\n    const c=cv.getContext("2d"),W=cv.width;draw(c,bolt(W/2,cv.height/2,W/2/3.4,W/210));});},800);}\n  else requestAnimationFrame(tick);\n})();\n'
V5_CSS = '\n/* Thunderstorm, the tier above On fire (17 Oct 2026, Christopher; build/storm_tier.py): hot, 7+ games and 2.5+ NHL\n   points a game.  Fourth version, same night ("more subtle", then Super Saiyan 2 style, then "high quality\n   lightning"): a bigger flame, a soft blue ring that pulses around the portrait, and real lightning drawn live on a\n   small canvas: every bolt is generated fresh (fractal, forked, flickering, white core in a blue glow) and crackles\n   off the rim at random.  Every few seconds one jumps off the portrait, bounces off his name and into his stats line\n   (a second canvas over the row).  Paused off screen; one still bolt under reduced motion. */\n.fw.storm{--fls:1.4}\n.fw.storm>.fbolt{position:absolute;z-index:2;pointer-events:none;left:-120%;right:-120%;top:-120%;bottom:-120%}\n.fw.storm>.fbolt::before{content:"";position:absolute;inset:33.5%;border-radius:50%;background:radial-gradient(circle,rgba(170,220,255,0) 55%,rgba(170,220,255,.42) 64%,rgba(120,190,255,0) 74%);animation:staura 1.6s ease-in-out infinite}\n.fw.storm>.fbolt canvas{position:absolute;inset:0;width:100%;height:100%;display:block}\n.fw.storm>.face{box-shadow:0 0 0 1.5px rgba(200,235,255,.7);animation:string 1.6s ease-in-out infinite}\n@keyframes staura{0%,100%{opacity:.35;transform:scale(.97)}50%{opacity:.9;transform:scale(1.04)}}\n@keyframes string{0%,100%{box-shadow:0 0 0 1.5px rgba(200,235,255,.55),0 0 8px 1px rgba(120,190,255,.25)}50%{box-shadow:0 0 0 1.5px rgba(220,242,255,.9),0 0 16px 3px rgba(120,190,255,.45)}}\n.li:has(.fw.storm){position:relative}\n.li>canvas.strow{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:3}\n@media(prefers-reduced-motion:reduce){.fw.storm>.fbolt::before,.fw.storm>.face{animation:none!important}}'
V5_JS = '/* Thunderstorm tier (17 Oct 2026; build/storm_tier.py): above On fire, for a hot run of 2.5+ NHL points a game over 7+ games */\nfunction isStorm(x){return !!x&&x.k==="hot"&&(x.gp||0)>=7&&(x.ppg||0)>=2.5;}\nfunction boltArt(){return `<i class="fbolt"><canvas aria-hidden="true"></canvas></i>`;}\n/* the lightning: one loop for every storm portrait on the page; each canvas keeps its own bolts */\n(function(){\n  if(window.__stormLoop)return;window.__stormLoop=1;\n  const still=matchMedia("(prefers-reduced-motion: reduce)").matches,ST=new WeakMap(),R=(a,b)=>a+Math.random()*(b-a);\n  /* a fractal bolt: midpoint displacement, then forks that branch off and taper */\n  function path(x1,y1,x2,y2,rough,depth){let p=[[x1,y1],[x2,y2]];\n    for(let d=0;d<depth;d++){const n=[p[0]];for(let i=1;i<p.length;i++){const [ax,ay]=p[i-1],[bx,by]=p[i],dx=bx-ax,dy=by-ay,L=Math.hypot(dx,dy),o=R(-1,1)*L*rough;\n      n.push([(ax+bx)/2-dy/L*o,(ay+by)/2+dx/L*o],[bx,by]);}p=n;rough*=.72;}return p;}\n  function bolt(cx,cy,r,s){const a=R(0,Math.PI*2)-(Math.random()<.55?Math.PI/2*R(0,1):0),r0=r*R(.9,1),len=r*R(.95,1.75),b=a+R(-.45,.45);\n    const main=path(cx+Math.cos(a)*r0,cy+Math.sin(a)*r0,cx+Math.cos(b)*(r0+len),cy+Math.sin(b)*(r0+len),.62,7),segs=[{p:main,w:1}];\n    for(let k=0;k<4;k++){if(Math.random()<.7){const i=(main.length*R(.2,.75))|0,[bx,by]=main[i],ba=Math.atan2(by-cy,bx-cx)+R(-1,1),bl=len*R(.25,.5);\n      const br=path(bx,by,bx+Math.cos(ba)*bl,by+Math.sin(ba)*bl,.6,6);segs.push({p:br,w:.55});\n      if(Math.random()<.4){const j=(br.length*R(.3,.7))|0,[qx,qy]=br[j],qa=ba+R(-1,1),ql=bl*R(.3,.5);segs.push({p:path(qx,qy,qx+Math.cos(qa)*ql,qy+Math.sin(qa)*ql,.5,4),w:.3});}}}\n    return {segs,life:0,max:R(11,18)|0,hx:main[0][0],hy:main[0][1],s};}\n  const FLK=[1,.35,1,.85,.2,.9,.6,.3,.75,.45,.2,.5,.3,.15,.25,.1];\n  function draw(c,b){const f=FLK[Math.min(FLK.length-1,b.life)]*(1-b.life/b.max*.4);if(f<=0)return;\n    c.globalCompositeOperation="lighter";\n    for(const [gx,gy,gr] of (b.glows||[[b.hx,b.hy,18]])){const g=c.createRadialGradient(gx,gy,0,gx,gy,b.s*gr);g.addColorStop(0,`rgba(140,200,255,${.2*f})`);g.addColorStop(1,"rgba(140,200,255,0)");c.fillStyle=g;c.fillRect(gx-b.s*gr,gy-b.s*gr,b.s*gr*2,b.s*gr*2);}\n    for(const [col,wd,al,blur] of [["70,150,255",4.2,.38,10],["170,220,255",1.8,.95,5],["255,255,255",.85,1,2]]){\n      c.strokeStyle=`rgba(${col},${al*f})`;c.shadowColor=`rgba(${col},${f})`;c.shadowBlur=blur*b.s;\n      for(const sg of b.segs){c.lineWidth=wd*sg.w*b.s;c.beginPath();sg.p.forEach((q,i)=>i?c.lineTo(q[0],q[1]):c.moveTo(q[0],q[1]));c.stroke();}}\n    c.shadowBlur=0;}\n  /* every few seconds: a bolt off the portrait that bounces off his name and on into his stats line */\n  function chain(li,cv,dpr){const L=li.getBoundingClientRect(),q=e=>e&&e.getBoundingClientRect(),fw=q(li.querySelector(".fw.storm")),nm=q(li.querySelector(".nm")),ln=q(li.querySelector(".ln2"));\n    if(!fw||!nm||!ln)return [];const X=v=>(v-L.left)*dpr,Y=v=>(v-L.top)*dpr,s=dpr*.62;\n    const fx=X(fw.left+fw.width/2),fy=Y(fw.top+fw.height/2),fr=fw.width/2*dpr,a=R(-.5,.35);\n    const p0=[fx+Math.cos(a)*fr,fy+Math.sin(a)*fr],p1=[X(nm.left+nm.width*R(.25,.8)),Y(nm.top+nm.height*R(.35,.65))],p2=[X(ln.left+ln.width*R(.35,.95)),Y(ln.top+ln.height*R(.4,.6))];\n    const mk=(A,B,d)=>{const m=path(A[0],A[1],B[0],B[1],.2,7),segs=[{p:m,w:1}];if(Math.random()<.7){const i=(m.length*R(.3,.7))|0,[bx,by]=m[i],ba=Math.atan2(B[1]-A[1],B[0]-A[0])+R(-1.1,1.1),bl=Math.hypot(B[0]-A[0],B[1]-A[1])*R(.15,.3);\n      segs.push({p:path(bx,by,bx+Math.cos(ba)*bl,by+Math.sin(ba)*bl,.5,5),w:.5});}return {segs,life:-d,max:R(12,17)|0,s,glows:[[A[0],A[1],10],[B[0],B[1],16]]};};\n    return [mk(p0,p1,0),mk(p1,p2,4)];}\n  function rowTick(cv){const li=cv.closest(".li");if(!li)return;let rc=li.querySelector(":scope>canvas.strow");\n    if(!rc){rc=document.createElement("canvas");rc.className="strow";rc.setAttribute("aria-hidden","true");li.appendChild(rc);}\n    const L=li.getBoundingClientRect(),dpr=Math.min(3,devicePixelRatio||1),W=Math.round(L.width*dpr),H=Math.round(L.height*dpr);if(!W)return;\n    if(rc.width!==W||rc.height!==H){rc.width=W;rc.height=H;}\n    let st=ST.get(rc);if(!st){st={b:[],next:R(40,90)|0};ST.set(rc,st);}\n    const c=rc.getContext("2d");c.setTransform(1,0,0,1,0,0);c.clearRect(0,0,W,H);\n    if(--st.next<=0){st.b.push(...chain(li,rc,dpr));st.next=R(130,240)|0;}\n    for(let i=st.b.length-1;i>=0;i--){const b=st.b[i];if(b.life>=0)draw(c,b);b.life++;if(b.life>=b.max)st.b.splice(i,1);}}\n  function tick(){const vh=innerHeight;\n    document.querySelectorAll(".fw.storm>.fbolt>canvas").forEach(cv=>{const rc=cv.getBoundingClientRect();if(!rc.width||rc.bottom<0||rc.top>vh)return;\n      let st=ST.get(cv);const dpr=Math.min(3,devicePixelRatio||1),W=Math.round(rc.width*dpr),H=Math.round(rc.height*dpr);\n      if(!st){st={b:[],next:R(4,20)|0};ST.set(cv,st);}\n      if(cv.width!==W||cv.height!==H){cv.width=W;cv.height=H;}\n      const c=cv.getContext("2d"),cx=W/2,cy=H/2,r=W/2/3.4,s=W/(210*dpr);\n      c.setTransform(1,0,0,1,0,0);c.clearRect(0,0,W,H);\n      if(--st.next<=0){st.b.push(bolt(cx,cy,r,s*dpr));if(Math.random()<.3)st.b.push(bolt(cx,cy,r,s*dpr));st.next=R(8,30)|0;}\n      for(let i=st.b.length-1;i>=0;i--){const b=st.b[i];draw(c,b);b.life++;if(b.life>=b.max)st.b.splice(i,1);}\n      rowTick(cv);});\n    if(!still)requestAnimationFrame(tick);}\n  if(still){setTimeout(()=>{document.querySelectorAll(".fw.storm>.fbolt>canvas").forEach(cv=>{const rc=cv.getBoundingClientRect(),d=Math.min(2,devicePixelRatio||1);cv.width=rc.width*d;cv.height=rc.height*d;\n    const c=cv.getContext("2d"),W=cv.width;draw(c,bolt(W/2,cv.height/2,W/2/3.4,W/210));});},800);}\n  else requestAnimationFrame(tick);\n})();\n'
SWAPS = [
    ("return {cls:` ${x.k} l${l}`,bg:`<i class=\"fbg\">${art}</i>`,title:`${stkWord(x.k,l)}, per Frozen Pool: ${stkWhy(x)}`};}",
     "const st=isStorm(x);return {cls:` ${x.k} l${l}${st?\" storm\":\"\"}`,bg:`<i class=\"fbg\">${art}</i>${st?boltArt():\"\"}`,title:`${st?\"Thunderstorm\":stkWord(x.k,l)}, per Frozen Pool: ${stkWhy(x)}`};}"),
    ("return `<i class=\"strk ${x.k} l${l}\" title=\"${stkWord(x.k,l)}, per Frozen Pool: ${stkWhy(x)}\">",
     "return `<i class=\"strk ${x.k} l${l}${isStorm(x)?\" storm\":\"\"}\" title=\"${isStorm(x)?\"Thunderstorm\":stkWord(x.k,l)}, per Frozen Pool: ${stkWhy(x)}\">"),
]


def main(path):
    raw = open(path, "rb").read().decode("utf-8")
    crlf = "\r\n" in raw
    s = raw.replace("\r\n", "\n")
    for oc, oj in ((OLD_CSS, OLD_JS), (V2_CSS, V2_JS), (V3_CSS, V3_JS), (V4_CSS, V4_JS), (V5_CSS, V5_JS)):   # an earlier version: swap in this one
      if oc in s and oj in s:
        s = s.replace(oc, CSS_ADD, 1).replace(oj, JS_ADD, 1)
        if crlf:
            s = s.replace("\n", "\r\n")
        open(path, "wb").write(s.encode("utf-8"))
        print("patched: Thunderstorm updated (bounces at random, hits linger)")
        return
    if MARK in s:
        print("already patched, nothing to do")
        return
    pairs = [(CSS_ANCHOR, CSS_ANCHOR + CSS_ADD), (JS_ANCHOR, JS_ADD + JS_ANCHOR)] + SWAPS
    for old, _ in pairs:
        if s.count(old) != 1:
            sys.exit(f"stopped: a spot was found {s.count(old)} times (expected 1): {old[:70]!r}; nothing written")
    for old, new in pairs:
        s = s.replace(old, new, 1)
    if crlf:
        s = s.replace("\n", "\r\n")
    open(path, "wb").write(s.encode("utf-8"))
    print("patched: Thunderstorm tier")


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "index.html")
